CREATE OR REPLACE FUNCTION public.protect_work_order_quotation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE iid uuid; BEGIN iid:=CASE WHEN TG_OP='DELETE' THEN OLD.inspection_id ELSE NEW.inspection_id END; IF current_user NOT IN ('postgres','service_role','supabase_admin') AND (EXISTS(SELECT 1 FROM public.inspection_work_orders WHERE inspection_id=iid) OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.inspection_work_orders WHERE inspection_id=OLD.inspection_id))) THEN RAISE EXCEPTION 'use_quotation_revision'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.preserve_completed_work_state() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='done' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.repair_item_id IS DISTINCT FROM OLD.repair_item_id OR NEW.work_order_id IS DISTINCT FROM OLD.work_order_id OR NEW.actual_cost IS DISTINCT FROM OLD.actual_cost OR NEW.completed_at IS DISTINCT FROM OLD.completed_at) THEN RAISE EXCEPTION 'completed_work_is_immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER preserve_completed_work_state BEFORE UPDATE ON public.inspection_work_order_items FOR EACH ROW EXECUTE FUNCTION public.preserve_completed_work_state();